// model/view.mjs -- the bar widget, the guide body, the footer and the keyboard map. One part of Model.mjs (D-REL-5); its import and export lines are generated by split-model.mjs on the dev branch.
import {
  MAX_ROWS_DEFAULT, SCOPE_FAVORITES, SCOPE_ALL, ELLIPSIS, SEP, GLYPHS,
  CHNO_ENTRY_SEP
} from "./build.mjs"
import {
  str, asList, tokenize
} from "./text.mjs"
import {
  numberEntry, chnoStatus
} from "./channels.mjs"
import {
  effectiveScope, guideState, onEscape
} from "./browse.mjs"
import {
  hideAction, hideVerb
} from "./state.mjs"
import {
  WALL_KEY, arrowAction
} from "./logos.mjs"
import {
  finiteOr, clockSpan, spokenSpan, playbackStateText
} from "./rewind.mjs"
import {
  PIP_TOOLTIP_ON
} from "./pip.mjs"
import {
  formatCount, pluralChannels
} from "./epg.mjs"
import {
  PAUSE_KEY, TRACKS_KEY, DETAIL_KEY, REWIND_KEY, FORWARD_KEY, LIVE_KEY,
  BEHIND_LIVE_SHOW_S, HELP_KEY, SOURCE_KEYS, isUrlField, maskUrl
} from "./sources.mjs"
import {
  isFormField, formHasText
} from "./source-records.mjs"

// ------------------------------------------------------------ bar widget

// R7: glyph per state, never color-only.
function barGlyph(opts) {
  var o = opts || {}
  // PAUSE LIVE TV. R7 is that a bar state is never carried by colour alone,
  // so a paused stream gets its own glyph rather than the playing one dimmed.
  if (o.playing && o.paused) return GLYPHS.tvPause
  // M5-01 (design 2.5): playing behind live is a bar state of its own and
  // gets the history glyph; the `-m:ss` beside it carries the number. Paused
  // wins above it, because the pause glyph with the count-up is what 2.5
  // draws. Decided here rather than in the widget so a test can call it.
  if (o.playing && o.behindLive === true) return GLYPHS.history
  if (o.playing) return GLYPHS.tvPlay
  if (o.error) return GLYPHS.tvOff
  return GLYPHS.tv
}

// UX 6.3 tooltips. `serviceMissing` wins (ARCHITECTURE.md section 7).
//
// M2-05 section 5 / PIP2: when picture in picture is on the tooltip gains
// one LINE for it and nothing else changes - no new mouse gesture, and the
// glyph stays as it is, because PiP is a window state and the bar already
// carries playback truth. PIP9: the line says the window is in PiP, never
// that it is on top of anything.
function barTooltip(opts) {
  var o = opts || {}
  if (o.serviceMissing) return "IPTV" + SEP + "service not loaded, run omarchy restart shell"
  var line = ""
  // M2-03 6.4: the number joins the tooltip whenever the playing channel has
  // one, including on a vertical bar where the label itself is glyph-only.
  if (o.playing && str(o.name) !== "") {
    line = (o.paused ? "Paused " : "Playing ") + (str(o.chno) !== "" ? str(o.chno) + SEP : "") + str(o.name)
    // M5-01 (design 2.5): the state line the footer shows, plus the window
    // from the last read -- `up to 6:52 back`. On a channel whose window is
    // 7 s the number is 0:07, not a promise. `behindS` and `historyS` come
    // from the service's `rewind` object; absent, the tooltip is unchanged.
    // The first line already says Paused, so the state line here is the
    // number alone: `Paused 7 SEP BBC One` / `0:42 behind live SEP up to ...`,
    // not "Paused ... paused SEP 0:42" (seen on the live pass, F-UX-3).
    var state = playbackStateText({ paused: false, behindS: o.behindS })
    var window = finiteOr(o.historyS, 0)
    var extra = []
    if (state !== "") extra.push(state)
    // Only once there is a whole second of window: `b` is hinted on a
    // non-empty range, and "up to 0:00 back" in the first instant after a
    // zap (clockSpan of 0.4 s) would promise what the key cannot do.
    if (window >= 1) extra.push("up to " + clockSpan(window) + " back")
    if (extra.length > 0) line += "\n" + extra.join(SEP)
  }
  else if (o.refreshing) line = "IPTV" + SEP + "refreshing playlist" + ELLIPSIS
  else if (!o.configured) line = "IPTV" + SEP + "no playlist configured"
  else if (o.error) line = "IPTV" + SEP + "playlist error, open the guide"
  else line = "IPTV" + SEP + "click to open the guide"
  return o.pip === true ? line + "\n" + PIP_TOOLTIP_ON : line
}

function barAccessibleName(opts) {
  var o = opts || {}
  // PAUSE LIVE TV. The glyph and the tooltip both changed for paused; the
  // accessible name has to as well, or the one user who cannot see the glyph
  // is the one user not told. That asymmetry is exactly the D-GS-3 shape.
  if (o.playing && str(o.name) !== "") {
    var name = "IPTV, " + (o.paused ? "paused" : "playing") + " " + (str(o.chno) !== "" ? "channel " + str(o.chno) + ", " : "") + str(o.name)
    // M5-01: the same threshold the label and the footer use, spoken as
    // units ("1 minute 32 seconds behind live") rather than as a clock,
    // because "one thirty-two" is a time of day to a listener.
    var behind = finiteOr(o.behindS, 0)
    if (behind >= BEHIND_LIVE_SHOW_S) name += ", " + spokenSpan(behind) + " behind live"
    return name
  }
  if (o.error) return "IPTV, playlist error"
  return "IPTV, idle"
}

// ------------------------------------------------------------ guide body

// Which single surface the guide body renders (UX 4.4 - 4.6 / 6.3 and
// UX-SOURCES 1.2) and, with it, whether rows, the group column and the
// footer counts exist at all. One decision instead of three independent
// bindings, so an empty state can never be drawn on top of a channel list
// (D-LIVE-19: `omarchy bar set ... playlistUrl ""` at runtime flipped the
// body to `No playlist configured` while the service still held the
// previous source's channels, and the title, prose and command box were
// painted over 10 live rows and an 11-entry group column).
//
// The unconfigured rule is the fix: a guide without a configured playlist
// has no channels, no groups and no counts whatever the service still holds
// in memory, so the setup surface stands alone. `savedSources` carries the
// history size into that surface, because since v0.2.0 the source record
// outlives the cleared setting and the first-run screen must offer the
// `Saved sources (n)` path rather than pretend nothing was ever configured.
//
// opts: serviceReady, configured, channelCount (what the service holds),
// status (R8 vocabulary), rowCount (rows left after query and scope),
// query, scopeId, narrow, sources (records in the history), stateBlocked
// (Service.stateWriteBlocked: the no-write mode's reason, "" when off).
//
// R23e (D-SINK-19 round 13): an unconfigured guide in the no-write mode is
// NOT the setup surface. A start whose state.json could not be read has
// loaded nothing, so it looked exactly like a fresh install -- "No playlist
// configured" over a form whose submit was then refused -- and only the
// notification said that saved sources existed. It is "stateUnreadable"
// instead: an empty state whose words are Model.stateUnreadableNotice's,
// the notification's own, with no field (firstRunAllowed says the form is
// not opened). A guide that still HAS channels mid-session keeps them: the
// session's memory stands and plays, and the refusals say why (R23f).
function guideSurface(opts) {
  var o = opts || {}
  var ready = o.serviceReady !== false
  var configured = ready && o.configured === true
  var count = configured ? Math.max(0, Math.floor(Number(o.channelCount) || 0)) : 0
  var has = count > 0
  var empty = ""
  if (!ready) empty = "service"
  else if (!configured) empty = str(o.stateBlocked) !== "" ? "stateUnreadable" : "unconfigured"
  else if (!has) empty = str(o.status) === "error" ? "error" : "loading"
  else if (Math.floor(Number(o.rowCount) || 0) > 0) empty = ""
  else if (tokenize(o.query).length > 0) empty = "noMatches"
  else if (effectiveScope(o.scopeId, o.query) === SCOPE_FAVORITES) empty = "noFavorites"
  else empty = "emptyScope"
  return {
    empty: empty,
    channelCount: count,
    hasChannels: has,
    showList: has,
    // M2-13: the wall hides the group column, which is what frees the width
    // for bigger tiles and what lets h/l be horizontal cursor movement instead
    // of a group facet. Decided here so one function owns the answer.
    showColumn: has && o.narrow !== true && o.wall !== true,
    setup: empty === "unconfigured",
    savedSources: empty === "unconfigured" ? Math.max(0, Math.floor(Number(o.sources) || 0)) : 0
  }
}

// R23e: does an unconfigured guide open into, or return to, the first-run
// form? Not in the no-write mode -- its submit could only be refused, and
// the surface there is guideSurface's "stateUnreadable" -- and not before
// the service is attached. One decision for the four places the guide asks
// it (opening, `configured` or the mode flipping while open, and the Esc /
// `o` return from Sources).
function firstRunAllowed(opts) {
  var o = opts || {}
  return o.serviceReady !== false && o.configured !== true && str(o.stateBlocked) === ""
}

// ------------------------------------------------------------ footer

// The counts line of the footer (UX 6.1): how many channels are listed and
// how fresh the copy in use is. When the copy is stale it reads
// `cached HH:MM - offline`, which is the footer's only cue that a refresh
// failed and the guide is serving a cache (D-LIVE-22), so this line carries
// a state, not only a number.
function footerCounts(o) {
  var out = pluralChannels(o.count)
  if (str(o.lastUpdated) !== "") out += SEP + (o.stale ? "cached " + str(o.lastUpdated) + SEP + "offline" : "updated " + str(o.lastUpdated))
  else if (o.stale) out += SEP + "cached" + SEP + "offline"
  // UX-SOURCES 5.3: with two or more saved sources the counts line carries
  // the active source's label so a switch is visible at a glance.
  if (str(o.activeLabel) !== "" && Number(o.sourceCount) > 1) out = str(o.activeLabel) + SEP + out
  return out
}

// Is the guide serving a degraded copy? Today that is exactly the stale
// cache behind a failed or skipped refresh (Service `status === "cached"`);
// the name is the concept so a future degraded state joins this rung rather
// than sinking below the warnings.
function footerDegraded(o) {
  return !!(o && o.stale)
}

// Footer status (UX 6.1, precedence note in UX 6.3). Priority, highest
// first: transient > bounded search > playing > refreshing > degraded (the
// `cached HH:MM - offline` counts line) > EPG pending > helper warning
// (`o.warning`, from footerWarning: playlist first, then EPG; D-LIVE-18,
// until that helper's next clean load) > the plain counts line.
//
// D-LIVE-22: warnings are informational and must never hide a failure, and a
// stale cache is the failure side of that rule, not decoration. UX 6.3 ranks
// an error above both warning kinds; an error with no cache has no footer
// line at all (it speaks in the body), so the rung the degraded counts line
// takes here is that error rung - above EPG pending and above both warnings.
//
// The empty states (not configured, loading, error without a cache;
// UX 4.4 - 4.6) carry their message in the body and leave the status slot
// blank, so `0 channels` or `Refreshing...` never shows there (D-LIVE-09);
// only a transient may.
function footerStatus(opts) {
  var o = opts || {}
  // M2-03 6.2: a live number buffer sits at the TOP of the ladder, above the
  // transient. While the user is typing digits the footer is the running
  // report of what those digits resolve to, and a three-second transient
  // from an earlier action must not cover it.
  var entry = o.numberEntry
  if (entry && entry.active === true) {
    return chnoStatus(str(entry.kind), str(entry.kind) === "none" || str(entry.kind) === "" ? str(entry.buffer) : str(entry.label),
      str(entry.name), entry.matches, entry.ordinal, false)
  }
  if (str(o.transient) !== "") return str(o.transient)
  if (o.configured === false || !(Number(o.count) > 0)) return ""
  if (o.truncated) return "First " + formatCount(o.cap || MAX_ROWS_DEFAULT) + " of " + formatCount(o.resultTotal) + SEP + "keep typing"
  // M5-01 (design 2.5): the state line -- `1:32 behind live`, `paused SEP
  // 0:42 behind live` -- rides the playing line after the name, from the
  // same composer the bar reads (playbackStateText). "" at live adds nothing,
  // so the line the footer has shown since M1 is unchanged there.
  // The state LEADS the line, before the name: the footer status elides on
  // the right, a channel name can lose its tail and stay useful (the bar's
  // rule), and a number cannot. Composed after the name it was the first
  // casualty of a long name (F-UX-5, the review's UX lens).
  if (str(o.playingName) !== "") {
    var state = str(o.playbackState)
    return GLYPHS.play + " " + (state !== "" ? state + SEP : "") + str(o.playingName) + SEP + "s stop"
  }
  if (o.refreshing) return "Refreshing" + ELLIPSIS
  if (footerDegraded(o)) return footerCounts(o)
  if (o.epgPending) return "Guide data loading" + ELLIPSIS
  if (str(o.warning) !== "") return str(o.warning)
  // D-SAVE-1: below a warning, above the plain counts, and only in Favourites
  // (the caller passes "" everywhere else).
  if (str(o.savedSearches) !== "") return str(o.savedSearches)
  // D-HOST-1. Below a provider warning, which is more urgent, and above the
  // plain counts, which are what the footer shows most of the time -- so this
  // is seen without ever displacing something that needs acting on first.
  if (o.staleBuild === true) return "Updated" + SEP + "restart the shell to see the new version"
  return footerCounts(o)
}

// Footer hint pairs [key, verb] (UX 6.2, UX-SOURCES 5.3); the guide styles
// keys and verbs at different opacities. `o.form` is the open form (its
// focused element decides the set), `o.cursorKind` the Sources row kind,
// `o.sourcesExist` adds `o sources` to the error empty state.
// The word for what an arrow does, derived from arrowAction so the footer and
// the handler cannot disagree. "move" for a place in the sequence, "row" for
// a whole grid row, and the scope's own verb for the group facet.
function arrowVerb(o, axis) {
  var act = arrowAction({ axis: axis, delta: 1, wall: o && o.wall === true })
  if (act.target === "row") return "row"
  if (act.target === "cursor") return "move"
  return scopeVerb(o)
}

function footerHints(opts) {
  var o = opts || {}
  var mode = str(o.mode)
  if (mode === "confirmRemove" || mode === "confirmLogos") return [["Left/Right", "choose"], ["Enter", "confirm"], ["Esc", "cancel"]]
  if (mode === "tracks") return [["j/k", "move"], ["Enter", "select"], ["Esc", "back"]]
  // M4-02 / M4-04. The keys both panels actually handle, which is four and
  // not one. An earlier version of this line returned `Esc back` alone,
  // reasoning that a panel whose content fits needs no movement key -- but
  // the content does not always fit. The detail panel's description is the
  // one element in the plugin that WRAPS, Guide.qml's handlePanelKey takes
  // PageUp, PageDown, Home and End, and onMoveRequested pans on j/k, so on a
  // 600 character synopsis or a map taller than the card the user was left
  // with no on-screen cue that anything could move. A hint that lies by
  // omission is the one the footer was redesigned to stop telling.
  //
  // `Enter` is deliberately NOT here: onActivateRequested returns immediately
  // for `inPanel`, so Enter does nothing in either panel, and the track
  // picker's own line is where `Enter select` belongs. That is also why
  // keyboardMap no longer merges the picker and these two into one section.
  if (mode === "detail" || mode === "help") {
    return [["j/k", "scroll"], ["PgUp/PgDn", "page"], ["Home/End", "ends"], ["Esc", "back"]]
  }
  if (mode === "sourceEdit" || mode === "sourceXtream") return formHints(o.form)
  if (mode === "sources") {
    if (o.cursorKind === "add" || o.cursorKind === "xtream") return [["j/k", "move"], ["Enter", "open"], ["Esc", "back"]]
    // R24f: in the no-write mode nothing can be added, so neither add key is
    // hinted; with no source row either there is nothing to move to.
    if (str(o.stateBlocked) !== "") {
      if (o.cursorKind !== "source") return [["Esc", "back"]]
      return [["j/k", "move"], ["Enter", "switch"], [SOURCE_KEYS.edit, "edit"], [SOURCE_KEYS.remove, "remove"], [SOURCE_KEYS.logos, o.showLogos === true ? "logos off" : "logos on"], ["Esc", "back"]]
    }
    // M2-04: `g logos` reads the CURRENT state, so the key says what it will
    // do rather than what is on. A hint that always reads "logos" leaves the
    // user pressing it to find out, and finding out means contacting sixty-
    // three hosts.
    return [["j/k", "move"], ["Enter", "switch"], [SOURCE_KEYS.add, "add"], [SOURCE_KEYS.xtream, "Xtream"], [SOURCE_KEYS.edit, "edit"], [SOURCE_KEYS.remove, "remove"], [SOURCE_KEYS.logos, o.showLogos === true ? "logos off" : "logos on"], ["Esc", "back"]]
  }
  if (o.empty === "loading") return [["Esc", "close"]]
  if (o.empty) {
    // UX-SOURCES 5.3: `r retry`; `o.retry === false` drops it when nothing
    // can be retried (the configured value is invalid, D-SRC-06).
    var pairs = []
    if (o.retry !== false) pairs.push(["r", "retry"])
    if (o.sourcesExist) pairs.push([SOURCE_KEYS.open, "sources"])
    pairs.push(["Esc", "close"])
    return pairs
  }
  if (mode === "list") {
    // M2-03 6.3: while a number is being typed the hint line is the entry
    // line and nothing else. It is short on purpose, so the elide-left
    // footer keeps `Esc cancel` visible on the narrowest card.
    if (o.numberEntry && o.numberEntry.active === true) {
      return [["0-9", "digits"], [CHNO_ENTRY_SEP, "sub"], ["Enter", "play"], ["Backspace", "undo"], ["Esc", "cancel"]]
    }
    // M2-13: on the wall h/l move the cursor across a row instead of ringing
    // the scope, because the wall hides the group column. A hint that still
    // said "group" would name an axis the view does not have -- the same
    // mistake M2-09 D6 fixed for the list, in the other direction.
    // The verbs come from the SAME table the keys dispatch on, so the footer
    // cannot describe a movement the handler does not make. That drift is
    // what the 0.8.0 preflight blocked on.
    var list = [["j/k", arrowVerb(o, "v")], ["h/l", arrowVerb(o, "h")],
                ["Enter", "play"], ["Space", "preview"], ["f", "favorite"], ["s", "stop"]]
    // M3-01: `x` is hinted only where it hides or unhides, and the verb
    // comes from hideAction, the table the key dispatches on. In Recent and
    // Favorites the key keeps its older meaning and its older silence.
    var hide = hideVerb(o)
    if (hide !== "") list.push(["x", hide])
    // PAUSE LIVE TV. Only while something is playing -- a pause key on an
    // idle guide has nothing to act on and would be a hint that lies. Names
    // the direction, so nobody presses it to find out which way it goes.
    if (o.playing === true) list.push([PAUSE_KEY, o.paused === true ? "resume" : "pause"])
    // M5-01 (design 2.5). `b back` whenever something plays and the last
    // range read is non-empty (`canRewind`); `w forward` and `g live` only
    // while behind live, because a hint that does nothing is the lie the
    // footer was just redesigned to stop telling. Both flags are read
    // strictly, like `hasDetail`: the keys are new, and an absent flag has
    // no shipped wording to keep.
    if (o.playing === true && o.canRewind === true) list.push([REWIND_KEY, "back"])
    if (Number(o.behindLive) >= BEHIND_LIVE_SHOW_S) list.push([FORWARD_KEY, "forward"], [LIVE_KEY, "live"])
    // M3-02: gated the same way, for the same reason -- a picker with no
    // player to ask has nothing to show.
    if (o.playing === true) list.push([TRACKS_KEY, "tracks"])
    // M4-02. Gated STRICTLY (`=== true`, not `!== false`) and not the way
    // `pipAvailable` is, because this key is new: there is no shipped
    // wording an absent flag has to keep reading as. The flag is "this row
    // has a programme to show", and on the measurement that opened M4
    // (D-EPG-2: 0 of 1,453 rows carry one) hinting it unconditionally would
    // advertise a key that answers nothing on every install we have seen.
    if (o.hasDetail === true) list.push([DETAIL_KEY, "detail"])
    // M2-05 section 5. Gated the way `0-9` is: a machine with no Hyprland
    // never advertises a key that can only answer "picture in picture needs
    // Hyprland". An absent flag shows it, so a service that predates PiP is
    // not silently stripped of the hint.
    if (o.pipAvailable !== false) list.push(["p", "pip"])
    list.push(["r", "refresh"], ["/", "search"])
    // M2-13: after the action verbs and beside `/ search`, because both keys
    // change what you are LOOKING at rather than acting on the cursor -- and
    // because the footer elides from the left on a narrow card, so Enter,
    // Space, f and s must not be pushed off by a view toggle. Names the view
    // it will go TO, not the one you are in, so the key need not be pressed
    // to find out: the same rule the logos hint follows on Sources.
    list.push([WALL_KEY, o.wall === true ? "list" : "wall"])
    // Gated on the playlist actually having numbers, so an unnumbered source
    // gains no clutter and never advertises a key that does nothing.
    if (o.hasNumbers === true) list.push(["0-9", "channel"])
    list.push([SOURCE_KEYS.open, "sources"])
    // M4-04, LAST and ungated. The footer elides from the LEFT on a narrow
    // card, so the final segment is the one that always survives -- and the
    // key that says what the other fourteen are is the one that must. The
    // plan's own reason for the map is that this line is at its structural
    // limit; the way out of a full line is not to keep the way out off it.
    list.push([HELP_KEY, "help"])
    return list
  }
  // M2-13. Search mode gets the toggle too, and this is not symmetry for its
  // own sake: the guide OPENS in search mode, the key is handled there
  // (handleSharedKey serves both modes), and a key that works on the screen
  // the user starts on and is advertised only on the other one is a feature
  // nobody finds. It sits before Tab/Esc for the same elide reason as above.
  // On the wall Left/Right moves the cursor, so it stops naming an axis the
  // view does not have.
  var wall = o.wall === true
  if (str(o.query) !== "") {
    return [["Enter", "play"], ["Up/Down", arrowVerb(o, "v")],
            ["Left/Right", wall ? arrowVerb(o, "h") : "narrow"],
            [WALL_KEY, wall ? "list" : "wall"], ["Tab", "keys"], ["Esc", "clear"]]
  }
  // M4-04, and the one hint on this line a first-run user needs. `?` really
  // does work here -- handleSearchKey takes it while the query is empty, see
  // HELP_KEY -- and the guide OPENS on this screen, so leaving it unhinted
  // meant nothing on the first screen the user sees said the map exists, not
  // even the map's own key. LAST for the same elide reason as the list line:
  // the footer elides from the left, so the final segment is the one that
  // survives on a narrow card. Only on the EMPTY-query line, because the
  // moment there is query text `?` is a character again.
  return [["Enter", "play"], ["Up/Down", arrowVerb(o, "v")],
          ["Left/Right", arrowVerb(o, "h")],
          [WALL_KEY, wall ? "list" : "wall"], ["Tab", "keys"], ["Esc", "close"],
          [HELP_KEY, "help"]]
}

// M2-09 D6. The h/l ring still does something real on a one-group playlist --
// it rings Recent / Favorites / All -- so the pair is never dropped, only its
// verb stops naming an axis that is not on screen. Gated the way `hasNumbers`
// and `pipAvailable` are: an absent flag reads as the shipped wording, so a
// caller that predates this never loses a hint (engineering rule 10 (dev branch)). `scope`
// and `group` are both five characters, so the hint line does not move by a
// pixel and its existing left-elision is neither fixed nor worsened.
function scopeVerb(opts) {
  return (opts || {}).groupsNarrow === false ? "scope" : "group"
}

// Hints for an open form (UX-SOURCES 2.3 / 5.3): the submit verb is `load`
// on the first-run URL form, `save` elsewhere; Esc reads `cancel` for forms
// from Sources and `clear` / `back` / `close` for the first-run rule.
function formHints(form) {
  var f = form || {}
  if (f.probing) return [["Esc", "cancel"]]
  var firstRun = f.origin === "firstRun"
  var submit = firstRun && f.kind !== "xtream" ? "load" : "save"
  var esc = "cancel"
  if (firstRun) {
    if (formHasText(f)) esc = "clear"
    else esc = f.parent ? "back" : "close"
  }
  var focus = str(f.focus)
  if (!isFormField(f, focus)) return [["Enter", "activate"], ["Tab", "next field"], ["Esc", esc]]
  if (f.kind === "xtream") return [["Enter", submit], ["Tab", "next field"], ["Esc", esc]]
  var value = f.values ? str(f.values[focus]) : ""
  var maskable = isUrlField(focus) && maskUrl(value) !== value
  var revealed = maskable && !!(f.revealed && f.revealed[focus])
  if (maskable && !revealed) return [["Enter", submit], ["Tab", "next field"], [SOURCE_KEYS.reveal, "reveal"], [SOURCE_KEYS.paste, "replace"], ["Esc", esc]]
  if (revealed) return [["Enter", submit], ["Tab", "next field"], [SOURCE_KEYS.reveal, "hide"], ["Esc", esc]]
  return [["Enter", submit], ["Tab", "next field"], [SOURCE_KEYS.paste, "paste"], ["Esc", esc]]
}

// ------------------------------------------------------ keyboard map (M4-04)
//
// `?` opens a panel listing every key. The whole point of the feature is
// that it cannot drift, so it is BUILT BY CALLING the tables the rest of the
// product dispatches on -- footerHints, formHints, hideAction, onEscape,
// arrowAction (through footerHints' arrowVerb), SOURCE_KEYS, PAUSE_KEY,
// TRACKS_KEY, WALL_KEY, DETAIL_KEY, HELP_KEY and the number-entry branch --
// and never from a second hand-written list beside them.
//
// A hand-written map is the engineering rule 13 failure exactly: two
// statements of one fact joined by nothing but a name. This project has been
// bitten by that shape repeatedly -- the three arrow branches the 0.8.0
// preflight blocked on, the defect ledger's 32 drifted ids, the hide verb,
// the EPG-configured predicate -- and a help screen is the worst place for
// it, because the one user who reads it is the one who cannot tell it is
// wrong.
//
// WHAT THE MAP DOES NOT GATE. footerHints hides a key that cannot act right
// now (`playing`, `pipAvailable`, `hasNumbers`, `hasDetail`). The map does
// the opposite by default: it describes the grammar, and a help screen that
// hid the keys the user has not discovered yet would be useless on exactly
// the install that needs it. So keyboardMap() with no options shows
// everything, and `opts` only ever narrows it.
//
// WHAT CANNOT BE DERIVED. Five pairs, and they are in ONE named table below
// rather than scattered through the builder, so the gap is countable and a
// test can assert it has not grown. Each is a key Guide.qml dispatches on
// directly with no table in between:
//
//   Home, End, PageUp, PageDown -- handleSharedKey() branches on the Qt key
//     codes itself. The table that would close this is `listKeyAction(key,
//     opts)`, the Qt-key-code sibling of listLetterAction, returning
//     "first" / "last" / "page" / "" so the handler, the footer and this map
//     would all read one decision. It does not exist yet.
//   Ctrl+S (save the current search) -- handleSearchKey() branches on it and
//     no hint line names it; the same `listKeyAction` would cover it.
//   SOURCE_KEYS.clear (Ctrl+U) -- its KEY comes from SOURCE_KEYS, so half
//     the join holds; its MEANING is a literal because formHints never had
//     room for it. A `SOURCE_KEY_VERBS` map beside SOURCE_KEYS, one verb per
//     member, is what formHints and this would then share.
//
// Delete is a sixth key no table NAMES -- Guide.qml branches on
// Qt.Key_Delete, so `listKeyAction` would cover it too -- but it is not in
// the table above, because its MEANING is derived: in the list it reaches the
// same hideAction call `x` does (removeAt), and in Sources it is the remove
// action's twin, so it takes that verb rather than a second spelling of it.
// Esc is fully derived: in list mode it dispatches on Model.onEscape, and
// sameEscape() below proves list and search agree before the list borrows
// search's wording.
//
// A function and not a `var` only because SOURCE_KEYS is declared below
// this point in the file: a literal array here would read `undefined.clear`
// at module evaluation time.
function keyboardMapUntabled() {
  return [
    ["Channel list", "Home", "first channel"],
    ["Channel list", "End", "last channel"],
    ["Channel list", "PgUp/PgDn", "page up / down"],
    ["Search", "Ctrl+S", "save this search"],
    ["Source forms", SOURCE_KEYS.clear, "clear the field"]
  ]
}

// The word for `x` in the MAP, over hideAction's whole action vocabulary.
// Not hideVerb: the footer is deliberately SILENT on `x` in Recent and
// Favorites (M3-01), and inheriting that silence here would leave a key that
// does something off the one screen that lists what keys do. One table, two
// readings, and the difference is stated rather than duplicated.
function hideMeaning(opts) {
  var act = hideAction(opts).action
  if (act === "recent") return "remove from Recent"
  if (act === "favorite") return "remove from Favorites"
  if (act === "unhide") return "unhide this group"
  // "hide", and "none" -- which means no row is highlighted yet, so the key
  // takes this meaning the moment one is.
  return "hide this group"
}

// What Esc does in a mode, as a comparable string, straight out of the
// reducer the handler calls. Used to prove that list mode and search mode
// dispatch it identically before the list borrows search's wording, instead
// of assuming it: if the two ever diverge the list's Esc row disappears
// rather than describing the wrong one.
function escapeOutcome(mode, query) {
  var st = guideState(SCOPE_ALL)
  st.mode = str(mode)
  st.query = str(query)
  var r = onEscape(st, { configured: true })
  // The resulting MODE is compared as "changed or not", never by value: the
  // two modes trivially differ by their own name, and what has to match is
  // the BEHAVIOUR -- whether Esc closes the guide, whether it leaves the
  // mode, and what it leaves in the query.
  var moved = str(r.state.mode) !== str(mode) ? "mode-changed" : "same-mode"
  return (r.close === true ? "close" : "stay") + ":" + moved + ":" + str(r.state.query)
}

function sameEscape(a, b) {
  return escapeOutcome(a, "") === escapeOutcome(b, "") && escapeOutcome(a, "x") === escapeOutcome(b, "x")
}

// The meaning a set of [key, verb] pairs gives one key, "" when it names
// none. Lets one section borrow a pair another screen's table already
// spells, rather than spelling it a second time.
function verbForKey(pairs, key) {
  var list = asList(pairs)
  var want = str(key)
  for (var i = 0; i < list.length; i++) {
    var pair = asList(list[i])
    if (str(pair[0]) === want) return str(pair[1])
  }
  return ""
}

// Overwrite (or add) one key's meaning, for the two keys whose map wording
// is READ FROM A WIDER TABLE than the footer's -- `x` and Delete come from
// hideMeaning, which covers the two actions the footer is silent about, so
// the footer's narrower verb is replaced rather than joined to it.
function setKeyRow(rows, key, meaning) {
  var k = str(key)
  var m = str(meaning)
  if (k === "" || m === "") return rows
  for (var i = 0; i < rows.length; i++) if (rows[i][0] === k) { rows[i][1] = m; return rows }
  rows.push([k, m])
  return rows
}

// Merge [key, meaning] pairs into one section, first meaning first, and join
// two meanings for the same key with " / " (Esc really does read `clear` on
// a search with text and `close` on an empty one).
function mergeKeyRows(rows, pairs) {
  var list = asList(pairs)
  for (var i = 0; i < list.length; i++) {
    var pair = asList(list[i])
    var key = str(pair[0])
    var meaning = str(pair[1])
    if (key === "" || meaning === "") continue
    var at = -1
    for (var j = 0; j < rows.length; j++) if (rows[j][0] === key) { at = j; break }
    if (at === -1) { rows.push([key, meaning]); continue }
    if (rows[at][1].split(" / ").indexOf(meaning) === -1) rows[at][1] += " / " + meaning
  }
  return rows
}

// `opts` is the live guide context, all of it optional:
//   scopeId, query, channel, state   -> the `x` and Delete meaning, via hideAction
//   wall, groupsNarrow               -> the arrow verbs, via arrowAction
//   playing, paused, pipAvailable, hasNumbers, hasDetail, showLogos
//                                    -> only ever to NARROW the list
// -> [{ title, rows: [[key, meaning], ...] }, ...] in reading order.
function keyboardMap(opts) {
  var o = opts || {}
  function flag(name, dflt) { return o[name] === undefined ? dflt : o[name] === true }
  // The list-mode context, with everything available unless the caller says
  // otherwise. `mode` is forced: footerHints dispatches on it and the map
  // asks each screen's question itself.
  var list = {
    mode: "list", query: "", empty: "",
    scopeId: o.scopeId, channel: o.channel, state: o.state,
    wall: flag("wall", false), groupsNarrow: flag("groupsNarrow", true),
    playing: flag("playing", true), paused: flag("paused", false),
    pipAvailable: flag("pipAvailable", true), hasNumbers: flag("hasNumbers", true),
    hasDetail: flag("hasDetail", true), numberEntry: null,
    // M5-01: available unless the caller narrows, like every flag above --
    // the map describes the grammar and the footer gates. `behindLive` is
    // a number, so "available" is the threshold the footer shows it at.
    canRewind: flag("canRewind", true),
    behindLive: o.behindLive === undefined ? BEHIND_LIVE_SHOW_S : Number(o.behindLive)
  }
  var sections = []
  // 1. The channel list. footerHints gives the whole line.
  var listRows = mergeKeyRows([], footerHints(list))
  // Both views, so the h/l verb that belongs to the other one is listed too
  // (arrowAction, the table the handler dispatches on) and WALL_KEY carries
  // both of its words.
  var other = {}
  for (var k in list) other[k] = list[k]
  other.wall = !list.wall
  mergeKeyRows(listRows, footerHints(other))
  // `x` widened to hideAction's other two actions, which the footer omits on
  // purpose, and Delete which reaches the same hideAction call in removeAt().
  var hideWord = hideMeaning(o)
  setKeyRow(listRows, "x", hideWord)
  setKeyRow(listRows, "Delete", hideWord)
  // 2. Search, both the empty and the typed-in line, because Esc and
  // Left/Right change meaning between them.
  var searchRows = mergeKeyRows([], footerHints({ mode: "search", query: "", wall: list.wall, groupsNarrow: list.groupsNarrow }))
  mergeKeyRows(searchRows, footerHints({ mode: "search", query: "x", wall: list.wall, groupsNarrow: list.groupsNarrow }))
  // The list footer never hints Esc, but onEscape proves the two modes
  // dispatch it identically, so the list gets search's own wording.
  if (sameEscape("list", "search")) mergeKeyRows(listRows, [["Esc", verbForKey(searchRows, "Esc")]])
  sections.push({ title: "Channel list", rows: listRows })
  sections.push({ title: "Search", rows: searchRows })
  // 3. Channel numbers, from the number-entry branch of the same function.
  if (list.hasNumbers) sections.push({ title: "Channel numbers", rows: mergeKeyRows([], footerHints({ mode: "list", numberEntry: { active: true } })) })
  // 4. The panels, one footerHints call per mode, so a panel that gains a key
  // gains a row here. The keys that OPEN them are already in the channel-list
  // section, out of the same footer line, and are not restated.
  //
  // TWO SECTIONS, NOT ONE, and the reason is that merging them produced a
  // map that lied. mergeKeyRows unions the keys across the modes it is given,
  // so one "Panels" section carrying tracks + detail + help told the reader
  // `Enter select` -- true in the picker, and nothing at all in the other two,
  // where onActivateRequested returns immediately -- and, once the two
  // read-only panels gained their real movement rows, it would have had to
  // read `j/k move / scroll` for keys that do one or the other depending on
  // which panel is up. The map's whole job is to be the screen that does not
  // make you press a key to find out, so each row is filed under the panels
  // it is actually true on.
  sections.push({ title: "Audio and subtitles", rows: mergeKeyRows([], footerHints({ mode: "tracks" })) })
  var panelRows = mergeKeyRows([], footerHints({ mode: "detail" }))
  mergeKeyRows(panelRows, footerHints({ mode: "help" }))
  sections.push({ title: "Programme and Keys panels", rows: panelRows })
  // 5. Sources: the list, both cursor kinds, and the logos switch in the
  // state it is actually in. Delete is the remove key's twin, so it takes the
  // remove verb rather than a second spelling of it.
  var srcRows = mergeKeyRows([], footerHints({ mode: "sources", showLogos: flag("showLogos", false) }))
  mergeKeyRows(srcRows, footerHints({ mode: "sources", cursorKind: "add" }))
  mergeKeyRows(srcRows, [["Delete", verbForKey(srcRows, SOURCE_KEYS.remove)]])
  sections.push({ title: "Sources", rows: srcRows })
  // 6. The forms, over every branch of formHints that changes a key: a
  // maskable field, a revealed one, a plain one, Xtream, a focus that is not
  // a field at all, and a probing form.
  var formRows = []
  var forms = [
    { kind: "m3u", focus: "playlist", values: { playlist: "http://user:pass@host/get.php" } },
    { kind: "m3u", focus: "playlist", values: { playlist: "http://user:pass@host/get.php" }, revealed: { playlist: true } },
    { kind: "m3u", focus: "label", values: { label: "x" } },
    { kind: "xtream", focus: "server", values: { server: "x" } },
    { kind: "m3u", focus: "submit", values: {} },
    { kind: "m3u", focus: "playlist", values: {}, probing: true }
  ]
  for (var f = 0; f < forms.length; f++) mergeKeyRows(formRows, formHints(forms[f]))
  sections.push({ title: "Source forms", rows: formRows })
  // 7. Confirmations and the empty state, the last two screens footerHints
  // answers for.
  var elseRows = mergeKeyRows([], footerHints({ mode: "confirmRemove" }))
  mergeKeyRows(elseRows, footerHints({ mode: "list", empty: "error", retry: true, sourcesExist: true }))
  mergeKeyRows(elseRows, footerHints({ mode: "list", empty: "loading" }))
  sections.push({ title: "Confirmations and errors", rows: elseRows })
  // The pairs no table spells, each into the section it belongs to, LAST so
  // that a derived pair always wins the key if one ever appears.
  var untabled = keyboardMapUntabled()
  for (var u = 0; u < untabled.length; u++) {
    for (var s = 0; s < sections.length; s++) {
      if (sections[s].title === untabled[u][0]) {
        mergeKeyRows(sections[s].rows, [[untabled[u][1], untabled[u][2]]])
      }
    }
  }
  return sections
}

// Every key the map names, flattened and de-duplicated. The guide does not
// need this; the test that holds the join does, and so does anything that
// wants to ask whether a key is covered without walking the sections.
function keyboardMapKeys(opts) {
  var sections = keyboardMap(opts)
  var out = []
  for (var i = 0; i < sections.length; i++) {
    var rows = asList(sections[i].rows)
    for (var j = 0; j < rows.length; j++) if (out.indexOf(str(rows[j][0])) === -1) out.push(str(rows[j][0]))
  }
  return out
}
export {
  barGlyph, barTooltip, barAccessibleName, guideSurface, firstRunAllowed,
  footerCounts, footerDegraded, footerStatus, arrowVerb, footerHints,
  scopeVerb, formHints, keyboardMapUntabled, hideMeaning, escapeOutcome,
  sameEscape, verbForKey, setKeyRow, mergeKeyRows, keyboardMap,
  keyboardMapKeys
}
